entries.commands:
nmcli con show
nmcli con mod "{{con_name}}" ipv4.method manual ipv4.addresses {{ip_addr}}/{{prefix_len}}
nmcli con mod "{{con_name}}" ipv4.gateway {{gateway}}
nmcli con mod "{{con_name}}" ipv4.dns {{dns_ip}}
nmcli con up "{{con_name}}"
ip addr show {{ifname}}

systemctl status {{service_name}} --no-pager
systemctl restart {{service_name}}
systemctl enable --now {{service_name}}
journalctl -u {{service_name}} -n 50 --no-pager

# ---- 临时 ----
ip link add link {{ifname}} name {{ifname}}.{{vlan_id}} type vlan id {{vlan_id}}
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}.{{vlan_id}}
ip link set {{ifname}}.{{vlan_id}} up
# ---- 持久化（nmcli）----
nmcli con add type vlan con-name vlan{{vlan_id}} ifname {{ifname}}.{{vlan_id}} \
  dev {{ifname}} id {{vlan_id}} ipv4.method manual ipv4.addresses {{ip_addr}}/{{prefix_len}}
nmcli con up vlan{{vlan_id}}
ip -d link show {{ifname}}.{{vlan_id}}

# 临时生效：重启后丢失（持久化见 notes 里的配套条目）
ip link set {{ifname}} up
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}
ip addr show {{ifname}}
ip route get {{ip_addr}}

# ===== pip 离线安装 =====
# ---- 1.【有网侧】下载包及其全部依赖到目录（★ 必须与离网侧同 python 大版本 + 同平台架构）----
pip download {{pkg_name}} -d {{src_path}}
ls {{src_path}}
# ---- 2. 把整个 {{src_path}} 目录拷到离网机器（U 盘/内网，见传输工具条目）----
# ---- 3.【离网侧】本地目录安装（--no-index 禁用一切在线源）----
pip install --no-index --find-links {{src_path}} {{pkg_name}}
# ---- 4. 验证（import 名与包名可能不同，按实际包替换）----
pip show {{pkg_name}}
python3 -c "import <模块名>; print('OK')"

# ===== 连通性排查三连（openEuler）=====
# ---- 1. 基础连通（能通 = 二层+三层可达）----
ping -c 4 {{target}}
# ---- 2. 路径定位（-n 不解析域名，出在那一跳）----
traceroute -n {{target}}
# ---- 3. DNS 解析（IP 通但这里不通 = DNS 问题）----
dig +short {{domain}}
